import re

CC = re.compile(r'([\d,]+|\.)\s+\(\s*([\d.]+%)(?:,\s*([\d.]+%))?\)')
ROW = re.compile(r'^([<>])?\s*((?:(?:[\d,]+|\.)\s+\(\s*[\d.]+%(?:,\s*[\d.]+%)?\)\s+)+)(\S.*?)\s*$')
EVH = re.compile(r'^\s*(?:[A-Za-z0-9]+_{2,}\s*)+(?:\S.*)?$')
KV = re.compile(r'^([A-Za-z][^:]*?):\s+(.*?)\s*$')

def num(c):
    c2 = c.replace(',', '')
    return int(c2) if c2.isdigit() else c

def costs(s, events):
    rec = {}
    for i, (c, p1, p2) in enumerate(CC.findall(s)):
        ev = events[i] if i < len(events) else 'event%d' % i
        rec[ev] = num(c)
        rec[ev + ' %'] = p1
        if p2:
            rec[ev + ' cumul %'] = p2
    return rec

def parse(lines):
    skip = []
    meta = {}
    meta_l = []
    summ = []
    summ_l = []
    tops = []
    tops_l = []
    subs = []
    subs_l = []
    events = []
    sec = ''
    tb = False
    cur = ''
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if tb:
            skip.append(i)
            continue
        if line.startswith('Traceback (most recent call last)'):
            tb = True
            skip.append(i)
            continue
        if re.match(r'^-{10,}\s*$', line):
            skip.append(i)
            continue
        m = re.match(r'^--\s+(.*?)\s*$', line)
        if m:
            sec = m.group(1)
            skip.append(i)
            continue
        if sec == 'Metadata':
            m = KV.match(line)
            if m:
                meta[m.group(1)] = m.group(2)
                meta_l.append(i)
                if m.group(1) == 'Events shown':
                    events = m.group(2).split()
                continue
        if EVH.match(line):
            ev = re.findall(r'([A-Za-z0-9]+)_{2,}', line)
            if ev:
                events = ev
            skip.append(i)
            continue
        m = ROW.match(line)
        if not m:
            continue
        lead, cc, name = m.group(1), m.group(2), m.group(3)
        c = costs(cc, events)
        if sec == 'Summary':
            rec = {'name': name}
            rec.update(c)
            summ.append(rec)
            summ_l.append(i)
            continue
        pf = 'function' if sec.startswith('Function') else 'file'
        cf = 'file' if pf == 'function' else 'function'
        if lead:
            a, sep, b = name.rpartition(':')
            if not sep:
                a, b = name, ''
            cur = a
            rec = {'section': sec, pf: a, cf: b}
            rec.update(c)
            tops.append(rec)
            tops_l.append(i)
        else:
            rec = {'section': sec, pf: cur, cf: name}
            rec.update(c)
            subs.append(rec)
            subs_l.append(i)
    blocks = []
    if meta:
        blocks.append({'name': 'metadata', 'kind': 'kv', 'lines': meta_l, 'records': [meta]})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'table', 'lines': summ_l, 'records': summ})
    if tops:
        blocks.append({'name': 'groups', 'kind': 'table', 'lines': tops_l, 'records': tops})
    if subs:
        blocks.append({'name': 'entries', 'kind': 'table', 'lines': subs_l, 'records': subs})
    return {'blocks': blocks, 'skip': skip}
